/****************************************************************************
 * Private Functions - Connection Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: ai_ble_connected_cb
 *
 * Description:
 *   Called when a central device connects. Runs in BLE stack context.
 *
 ****************************************************************************/

static void ai_ble_connected_cb(FAR struct bt_conn_s *conn,
                                FAR void *context)
{
  FAR struct ai_watch_ble_state_s *ble = context;

  printf("BLE: Device connected\n");
  if (ble != NULL)
    {
      ble->state = BLE_STATE_CONNECTED;
    }
}

/****************************************************************************
 * Name: ai_ble_disconnected_cb
 *
 * Description:
 *   Called when the central device disconnects. Restarts advertising.
 *
 ****************************************************************************/

static void ai_ble_disconnected_cb(FAR struct bt_conn_s *conn,
                                   FAR void *context)
{
  FAR struct ai_watch_ble_state_s *ble = context;
  struct btreq_s btreq;
  int sockfd;
  int ret;

  printf("BLE: Device disconnected\n");
  if (ble != NULL)
    {
      ble->state = BLE_STATE_DISCONNECTED;
    }

  /* Restart advertising so another device can connect */

  memset(&btreq, 0, sizeof(btreq));
  strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
  btreq.btr_advtype = BT_LE_ADV_IND;

  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
  if (sockfd >= 0)
    {
      ret = ioctl(sockfd, SIOCBTADVSTART,
                  (unsigned long)((uintptr_t)&btreq));
      if (ret < 0)
        {
          printf("BLE: Restart advertising failed: %d\n", errno);
        }
      else
        {
          printf("BLE: Advertising restarted\n");
          if (ble != NULL)
            {
              ble->state = BLE_STATE_ADVERTISING;
            }
        }

      close(sockfd);
    }
}

/****************************************************************************
 * Private Functions - BLE Thread
 ****************************************************************************/

/****************************************************************************
 * Name: ai_ble_wait_for_interface
 *
 * Description:
 *   Poll until the BT network interface (bnep0) appears.
 *
 * Returned Value:
 *   0 on success, -ETIMEDOUT if interface never appears.
 *
 ****************************************************************************/

static int ai_ble_wait_for_interface(void)
{
  int retry;

  for (retry = 0; retry < BLE_IFACE_POLL_MAX; retry++)
    {
      struct btreq_s btreq;
      int sockfd;
      int ret;

      sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
      if (sockfd < 0)
        {
          usleep(BLE_IFACE_POLL_MS * 1000);
          continue;
        }

      memset(&btreq, 0, sizeof(btreq));
      strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);

      ret = ioctl(sockfd, SIOCGBTINFO,
                  (unsigned long)((uintptr_t)&btreq));
      close(sockfd);

      if (ret == 0)
        {
          printf("BLE: Interface %s ready after %d ms\n",
                 BLE_BTDEV_NAME, retry * BLE_IFACE_POLL_MS);
          return 0;
        }

      usleep(BLE_IFACE_POLL_MS * 1000);
    }

  printf("BLE: Interface %s not found after %d ms\n",
         BLE_BTDEV_NAME, BLE_IFACE_POLL_MAX * BLE_IFACE_POLL_MS);
  return -ETIMEDOUT;
}

/****************************************************************************
 * Name: ai_ble_start_advertising
 *
 * Description:
 *   Start BLE advertising with the device name in scan response.
 *
 * Returned Value:
 *   0 on success, negative errno on failure.
 *
 ****************************************************************************/

static int ai_ble_start_advertising(void)
{
  struct btreq_s btreq;
  int sockfd;
  int ret;

  memset(&btreq, 0, sizeof(btreq));
  strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
  btreq.btr_advtype = BT_LE_ADV_IND;

  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
  if (sockfd < 0)
    {
      printf("BLE: Socket create failed: %d\n", errno);
      return -errno;
    }

  ret = ioctl(sockfd, SIOCBTADVSTART,
              (unsigned long)((uintptr_t)&btreq));
  close(sockfd);

  if (ret < 0)
    {
      printf("BLE: SIOCBTADVSTART failed: %d\n", errno);
      return -errno;
    }

  printf("BLE: Advertising started\n");
  return 0;
}

/****************************************************************************
 * Name: ai_ble_thread
 *
 * Description:
 *   Background thread that initializes BLE, registers the GATT service,
 *   and starts advertising. The main thread continues without blocking.
 *
 ****************************************************************************/

static int ai_ble_thread(int argc, FAR char *argv[])
{
  FAR struct ai_watch_ble_state_s *ble;
  int ret;

  /* Recover the state pointer passed via argv */

  ble = (FAR struct ai_watch_ble_state_s *)
        ((uintptr_t)strtoul(argv[1], NULL, 16));

  if (ble == NULL)
    {
      printf("BLE: NULL state pointer\n");
      return -EINVAL;
    }

  printf("BLE: Thread started, waiting for interface...\n");

  /* Step 1: Wait for the BT network interface */

  ret = ai_ble_wait_for_interface();
  if (ret < 0)
    {
      ble->state = BLE_STATE_INIT_FAILED;
      printf("BLE: Init failed — interface timeout\n");
      return ret;
    }

  /* Step 2: Register connection callbacks */

  g_conn_cb.connected = ai_ble_connected_cb;
  g_conn_cb.disconnected = ai_ble_disconnected_cb;
  g_conn_cb.context = ble;
  bt_conn_cb_register(&g_conn_cb);
  printf("BLE: Connection callbacks registered\n");

  /* Step 3: Register custom GATT service */

  bt_gatt_register(g_ai_attrs, nitems(g_ai_attrs));
  printf("BLE: GATT service registered (attrs=%d)\n",
         (int)nitems(g_ai_attrs));

  /* Step 4: Start advertising */

  ret = ai_ble_start_advertising();
  if (ret < 0)
    {
      ble->state = BLE_STATE_INIT_FAILED;
      printf("BLE: Init failed — advertising error\n");
      return ret;
    }

  ble->state = BLE_STATE_ADVERTISING;
  ble->initialized = true;
  printf("BLE: Initialization complete, advertising as %s\n",
         AI_WATCH_BLE_DEVICE_NAME);

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_watch_ble_init
 ****************************************************************************/

int ai_watch_ble_init(FAR struct ai_watch_ble_state_s *ble_state)
{
  FAR char *thread_argv[2];
  char ptr_str[20];
  int ret;

  if (ble_state == NULL)
    {
      return -EINVAL;
    }

  memset(ble_state, 0, sizeof(*ble_state));
  ble_state->state = BLE_STATE_OFF;
  g_ble = ble_state;

  /* Pass state pointer as hex string in argv */

  snprintf(ptr_str, sizeof(ptr_str), "%lx",
           (unsigned long)((uintptr_t)ble_state));
  thread_argv[0] = ptr_str;
  thread_argv[1] = NULL;

  ret = task_create("ai_ble", BLE_THREAD_PRIORITY,
                    BLE_THREAD_STACKSIZE, ai_ble_thread,
                    thread_argv);
  if (ret < 0)
    {
      int errcode = errno;

      printf("ERROR: BLE thread create failed: %d\n", errcode);
      ble_state->state = BLE_STATE_INIT_FAILED;
      return -errcode;
    }

  printf("BLE: Thread launched (pid=%d)\n", ret);
  return 0;
}

/****************************************************************************
 * Name: ai_watch_ble_update
 ****************************************************************************/

void ai_watch_ble_update(FAR struct ai_watch_ble_state_s *ble_state)
{
  struct timespec ts;
  struct tm tm;

  if (ble_state == NULL || !ble_state->timesync_pending)
    {
      return;
    }

  /* Process pending time sync — this runs in the main/LVGL thread */

  ble_state->timesync_pending = false;

  /* Set system time using clock_settime.
   * The received UTC seconds are stored directly; timezone offset
   * is noted but the system clock runs in UTC.
   */

  ts.tv_sec = (time_t)ble_state->pending_sync.utc_seconds;
  ts.tv_nsec = 0;

  if (clock_settime(CLOCK_REALTIME, &ts) < 0)
    {
      printf("BLE: clock_settime failed: %d\n", errno);
      return;
    }

  ble_state->last_sync_time = ts.tv_sec;

  if (localtime_r(&ts.tv_sec, &tm) != NULL)
    {
      printf("BLE: Time synced: %04d-%02d-%02d %02d:%02d:%02d "
             "(tz=%+d min)\n",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec,
             ble_state->pending_sync.tz_offset_min);
    }
}

