136	/****************************************************************************
137	 * Name: ai_ble_read_status
138	 *
139	 * Description:
140	 *   Read callback for the status characteristic. Returns protocol version,
141	 *   connection state, and last sync time.
142	 *
143	 ****************************************************************************/
144	
145	static int ai_ble_read_status(FAR struct bt_conn_s *conn,
146	                              FAR const struct bt_gatt_attr_s *attr,
147	                              FAR void *buf, uint8_t len, uint16_t offset)
148	{
149	  uint8_t status[AI_WATCH_BLE_STATUS_SIZE];
150	  time_t sync;
151	
152	  status[0] = AI_WATCH_BLE_PROTOCOL_VERSION;
153	  status[1] = (g_ble != NULL && g_ble->state == BLE_STATE_CONNECTED) ?
154	               1 : 0;
155	
156	  sync = (g_ble != NULL) ? g_ble->last_sync_time : 0;
157	  memcpy(&status[2], &sync, 4);
158	
159	  return bt_gatt_attr_read(conn, attr, buf, len, offset,
160	                           status, sizeof(status));
161	}
