163	/****************************************************************************
164	 * Name: ai_ble_write_timesync
165	 *
166	 * Description:
167	 *   Write callback for the time sync characteristic. Validates the
168	 *   payload and sets the pending flag for the main thread to process.
169	 *   This runs in the BLE stack context — no LVGL calls allowed.
170	 *
171	 ****************************************************************************/
172	
173	static int ai_ble_write_timesync(FAR struct bt_conn_s *conn,
174	                                 FAR const struct bt_gatt_attr_s *attr,
175	                                 FAR const void *buf, uint8_t len,
176	                                 uint16_t offset)
177	{
178	  FAR const uint8_t *data = buf;
179	  struct ai_watch_ble_timesync_s sync;
180	
181	  /* Strict validation: exact length, version, and range checks */
182	
183	  if (len != AI_WATCH_BLE_TIMESYNC_SIZE)
184	    {
185	      printf("BLE: TimeSync rejected: bad len %u (expected %d)\n",
186	             len, AI_WATCH_BLE_TIMESYNC_SIZE);
187	      return -EINVAL;
188	    }
189	
190	  if (data[0] != AI_WATCH_BLE_PROTOCOL_VERSION)
191	    {
192	      printf("BLE: TimeSync rejected: version %u (expected %d)\n",
193	             data[0], AI_WATCH_BLE_PROTOCOL_VERSION);
194	      return -EINVAL;
195	    }
196	
197	  /* Parse little-endian fields */
198	
199	  sync.version = data[0];
200	  memcpy(&sync.utc_seconds, &data[1], 4);
201	  memcpy(&sync.tz_offset_min, &data[5], 2);
202	
203	  /* Sanity check: UTC seconds should be after 2020-01-01 and before
204	   * 2100-01-01 (seconds since epoch).
205	   *   2020-01-01 00:00:00 UTC = 1577836800
206	   *   2100-01-01 00:00:00 UTC = 4102444800
207	   */
208	
209	  if (sync.utc_seconds < 1577836800u ||
210	      sync.utc_seconds > 4102444800u)
211	    {
212	      printf("BLE: TimeSync rejected: UTC %lu out of range\n",
213	             (unsigned long)sync.utc_seconds);
214	      return -EINVAL;
215	    }
216	
217	  /* Timezone offset: -12h to +14h in minutes */
218	
219	  if (sync.tz_offset_min < -720 || sync.tz_offset_min > 840)
220	    {
221	      printf("BLE: TimeSync rejected: tz %d min out of range\n",
222	             sync.tz_offset_min);
223	      return -EINVAL;
224	    }
225	
226	  if (g_ble == NULL)
227	    {
228	      return -EFAULT;
229	    }
230	
231	  /* Store for main thread processing */
232	
233	  memcpy(&g_ble->pending_sync, &sync, sizeof(sync));
234	  g_ble->timesync_pending = true;
235	
236	  printf("BLE: TimeSync accepted: UTC=%lu tz=%d min\n",
237	         (unsigned long)sync.utc_seconds, sync.tz_offset_min);
238	  return len;
239	}
