339	/****************************************************************************
340	 * Name: ai_ble_disconnected_cb
341	 *
342	 * Description:
343	 *   Called when the central device disconnects. Restarts advertising.
344	 *
345	 ****************************************************************************/
346	
347	static void ai_ble_disconnected_cb(FAR struct bt_conn_s *conn,
348	                                   FAR void *context)
349	{
350	  FAR struct ai_watch_ble_state_s *ble = context;
351	  struct btreq_s btreq;
352	  int sockfd;
353	  int ret;
354	
355	  printf("BLE: Device disconnected\n");
356	  if (ble != NULL)
357	    {
358	      ble->state = BLE_STATE_DISCONNECTED;
359	    }
360	
361	  /* Restart advertising so another device can connect */
362	
363	  memset(&btreq, 0, sizeof(btreq));
364	  strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
365	  btreq.btr_advtype = BT_LE_ADV_IND;
366	
367	  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
368	  if (sockfd >= 0)
369	    {
370	      ret = ioctl(sockfd, SIOCBTADVSTART,
371	                  (unsigned long)((uintptr_t)&btreq));
372	      if (ret < 0)
373	        {
374	          printf("BLE: Restart advertising failed: %d\n", errno);
375	        }
376	      else
377	        {
378	          printf("BLE: Advertising restarted\n");
379	          if (ble != NULL)
380	            {
381	              ble->state = BLE_STATE_ADVERTISING;
382	            }
383	        }
384	
385	      close(sockfd);
386	    }
387	}
