393	/****************************************************************************
394	 * Name: ai_ble_wait_for_interface
395	 *
396	 * Description:
397	 *   Poll until the BT network interface (bnep0) appears.
398	 *
399	 * Returned Value:
400	 *   0 on success, -ETIMEDOUT if interface never appears.
401	 *
402	 ****************************************************************************/
403	
404	static int ai_ble_wait_for_interface(void)
405	{
406	  int retry;
407	
408	  for (retry = 0; retry < BLE_IFACE_POLL_MAX; retry++)
409	    {
410	      struct btreq_s btreq;
411	      int sockfd;
412	      int ret;
413	
414	      sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
415	      if (sockfd < 0)
416	        {
417	          usleep(BLE_IFACE_POLL_MS * 1000);
418	          continue;
419	        }
420	
421	      memset(&btreq, 0, sizeof(btreq));
422	      strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
423	
424	      ret = ioctl(sockfd, SIOCGBTINFO,
425	                  (unsigned long)((uintptr_t)&btreq));
426	      close(sockfd);
427	
428	      if (ret == 0)
429	        {
430	          printf("BLE: Interface %s ready after %d ms\n",
431	                 BLE_BTDEV_NAME, retry * BLE_IFACE_POLL_MS);
432	          return 0;
433	        }
434	
435	      usleep(BLE_IFACE_POLL_MS * 1000);
436	    }
437	
438	  printf("BLE: Interface %s not found after %d ms\n",
439	         BLE_BTDEV_NAME, BLE_IFACE_POLL_MAX * BLE_IFACE_POLL_MS);
440	  return -ETIMEDOUT;
441	}
