451	 *
452	 ****************************************************************************/
453	
454	static int ai_ble_start_advertising(void)
455	{
456	  struct btreq_s btreq;
457	  int sockfd;
458	  int ret;
459	
460	  memset(&btreq, 0, sizeof(btreq));
461	  strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
462	  btreq.btr_advtype = BT_LE_ADV_IND;
463	
464	  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
465	  if (sockfd < 0)
466	    {
467	      printf("BLE: Socket create failed: %d\n", errno);
468	      return -errno;
469	    }
470	
471	  ret = ioctl(sockfd, SIOCBTADVSTART,
472	              (unsigned long)((uintptr_t)&btreq));
473	  close(sockfd);
474	
475	  if (ret < 0)
476	    {
477	      printf("BLE: SIOCBTADVSTART failed: %d\n", errno);
478	      return -errno;
479	    }
480	
481	  printf("BLE: Advertising started\n");
482	  return 0;
483	}
