485	/****************************************************************************
486	 * Name: ai_ble_thread
487	 *
488	 * Description:
489	 *   Background thread that initializes BLE, registers the GATT service,
490	 *   and starts advertising. The main thread continues without blocking.
491	 *
492	 ****************************************************************************/
493	
494	static int ai_ble_thread(int argc, FAR char *argv[])
495	{
496	  FAR struct ai_watch_ble_state_s *ble;
497	  int ret;
498	
499	  /* Use the static global set by ai_watch_ble_init */
500	
501	  ble = g_ble;
502	  if (ble == NULL)
503	    {
504	      printf("BLE: NULL state pointer\n");
505	      return -EINVAL;
506	    }
507	
508	  printf("BLE: Thread started, waiting for interface...\n");
509	
510	  /* Step 1: Wait for the BT network interface */
511	
512	  ret = ai_ble_wait_for_interface();
513	  if (ret < 0)
514	    {
515	      ble->state = BLE_STATE_INIT_FAILED;
516	      printf("BLE: Init failed — interface timeout\n");
517	      return ret;
518	    }
519	
520	  /* Step 2: Register connection callbacks */
521	
522	  g_conn_cb.connected = ai_ble_connected_cb;
523	  g_conn_cb.disconnected = ai_ble_disconnected_cb;
524	  g_conn_cb.context = ble;
525	  bt_conn_cb_register(&g_conn_cb);
526	  printf("BLE: Connection callbacks registered\n");
527	
528	  /* Step 3: Register custom GATT service */
529	
530	  bt_gatt_register(g_ai_attrs, nitems(g_ai_attrs));
531	  printf("BLE: GATT service registered (attrs=%d)\n",
532	         (int)nitems(g_ai_attrs));
533	
534	  /* Step 4: Start advertising */
535	
536	  ret = ai_ble_start_advertising();
537	  if (ret < 0)
538	    {
539	      ble->state = BLE_STATE_INIT_FAILED;
540	      printf("BLE: Init failed — advertising error\n");
541	      return ret;
542	    }
543	
