/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>

#include <arpa/inet.h>
#include <netpacket/bluetooth.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <time.h>

#include <nuttx/wireless/bluetooth/bt_core.h>
#include <nuttx/wireless/bluetooth/bt_gatt.h>
#include <nuttx/wireless/bluetooth/bt_hci.h>
#include <nuttx/wireless/bluetooth/bt_ioctl.h>

#include "ai_watch_ble.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BLE_THREAD_STACKSIZE    4096
#define BLE_THREAD_PRIORITY     110
#define BLE_IFACE_POLL_MS       500
#define BLE_IFACE_POLL_MAX      60  /* 30 seconds max wait */

/* BT network device name used for ioctl */

#define BLE_BTDEV_NAME          "bnep0"

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* GATT CCC configuration for notify characteristics.
 * We support a single connection, so one entry is sufficient.
 */

static struct bt_gatt_ccc_cfg_s g_status_ccc_cfg[1];
static struct bt_gatt_ccc_cfg_s g_data_ccc_cfg[1];

/****************************************************************************
 * Private Data - Custom GATT Service UUIDs
 ****************************************************************************/

static struct bt_uuid_s g_ai_svc_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_SVC_UUID128,
};

static struct bt_uuid_s g_ai_status_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_STATUS_UUID128,
};

static struct bt_uuid_s g_ai_timesync_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_TIMESYNC_UUID128,
};

static struct bt_uuid_s g_ai_dataupload_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_DATAUPLOAD_UUID128,
};

/****************************************************************************
 * Private Data - Characteristic Declarations
 ****************************************************************************/

static struct bt_gatt_chrc_s g_status_chrc =
{
  .properties = BT_GATT_CHRC_READ | BT_GATT_CHRC_NOTIFY,
  .value_handle = AI_WATCH_BLE_HDL_STATUS_VAL,
  .uuid = &g_ai_status_uuid,
};

static struct bt_gatt_chrc_s g_timesync_chrc =
{
  .properties = BT_GATT_CHRC_WRITE,
  .value_handle = AI_WATCH_BLE_HDL_TIMESYNC_VAL,
  .uuid = &g_ai_timesync_uuid,
};

static struct bt_gatt_chrc_s g_dataupload_chrc =
{
  .properties = BT_GATT_CHRC_NOTIFY,
  .value_handle = AI_WATCH_BLE_HDL_DATA_VAL,
  .uuid = &g_ai_dataupload_uuid,
};

/****************************************************************************
 * Private Data - BLE State
 ****************************************************************************/

static FAR struct ai_watch_ble_state_s *g_ble;

/****************************************************************************
 * Private Functions - GATT Callbacks
 ****************************************************************************/

/****************************************************************************
 * Name: ai_ble_read_status
 *
 * Description:
 *   Read callback for the status characteristic. Returns protocol version,
 *   connection state, and last sync time.
 *
 ****************************************************************************/

static int ai_ble_read_status(FAR struct bt_conn_s *conn,
                              FAR const struct bt_gatt_attr_s *attr,
                              FAR void *buf, uint8_t len, uint16_t offset)
{
  uint8_t status[AI_WATCH_BLE_STATUS_SIZE];
  time_t sync;

  status[0] = AI_WATCH_BLE_PROTOCOL_VERSION;
  status[1] = (g_ble != NULL && g_ble->state == BLE_STATE_CONNECTED) ?
               1 : 0;

  sync = (g_ble != NULL) ? g_ble->last_sync_time : 0;
  memcpy(&status[2], &sync, 4);

  return bt_gatt_attr_read(conn, attr, buf, len, offset,
                           status, sizeof(status));
}

/****************************************************************************
 * Name: ai_ble_write_timesync
 *
 * Description:
 *   Write callback for the time sync characteristic. Validates the
 *   payload and sets the pending flag for the main thread to process.
 *   This runs in the BLE stack context — no LVGL calls allowed.
 *
 ****************************************************************************/

static int ai_ble_write_timesync(FAR struct bt_conn_s *conn,
                                 FAR const struct bt_gatt_attr_s *attr,
                                 FAR const void *buf, uint8_t len,
                                 uint16_t offset)
{
  FAR const uint8_t *data = buf;
  struct ai_watch_ble_timesync_s sync;

  /* Strict validation: exact length, version, and range checks */

  if (len != AI_WATCH_BLE_TIMESYNC_SIZE)
    {
      printf("BLE: TimeSync rejected: bad len %u (expected %d)\n",
             len, AI_WATCH_BLE_TIMESYNC_SIZE);
      return -EINVAL;
    }

  if (data[0] != AI_WATCH_BLE_PROTOCOL_VERSION)
    {
      printf("BLE: TimeSync rejected: version %u (expected %d)\n",
             data[0], AI_WATCH_BLE_PROTOCOL_VERSION);
      return -EINVAL;
    }

  /* Parse little-endian fields */

  sync.version = data[0];
  memcpy(&sync.utc_seconds, &data[1], 4);
  memcpy(&sync.tz_offset_min, &data[5], 2);

  /* Sanity check: UTC seconds should be after 2020-01-01 and before
   * 2100-01-01 (seconds since epoch).
   *   2020-01-01 00:00:00 UTC = 1577836800
   *   2100-01-01 00:00:00 UTC = 4102444800
   */

  if (sync.utc_seconds < 1577836800u ||
      sync.utc_seconds > 4102444800u)
    {
      printf("BLE: TimeSync rejected: UTC %lu out of range\n",
             (unsigned long)sync.utc_seconds);
      return -EINVAL;
    }

  /* Timezone offset: -12h to +14h in minutes */

  if (sync.tz_offset_min < -720 || sync.tz_offset_min > 840)
    {
      printf("BLE: TimeSync rejected: tz %d min out of range\n",
             sync.tz_offset_min);
      return -EINVAL;
    }

  if (g_ble == NULL)
    {
      return -EFAULT;
    }

  /* Store for main thread processing */

  memcpy(&g_ble->pending_sync, &sync, sizeof(sync));
  g_ble->timesync_pending = true;

  printf("BLE: TimeSync accepted: UTC=%lu tz=%d min\n",
         (unsigned long)sync.utc_seconds, sync.tz_offset_min);
  return len;
}

/****************************************************************************
 * Name: ai_ble_status_ccc_changed
 *
 * Description:
 *   Called when the client writes to the CCC descriptor of the status
 *   characteristic (subscribe/unsubscribe notifications).
 *
 ****************************************************************************/

static void ai_ble_status_ccc_changed(uint16_t value)
{
  printf("BLE: Status CCC changed: 0x%04x\n", value);
}

/****************************************************************************
 * Name: ai_ble_data_ccc_changed
 *
 * Description:
 *   Called when the client writes to the CCC descriptor of the data
 *   upload characteristic.
 *
 ****************************************************************************/

static void ai_ble_data_ccc_changed(uint16_t value)
{
  printf("BLE: DataUpload CCC changed: 0x%04x\n", value);
}

/****************************************************************************
 * Private Data - GATT Attribute Table
 ****************************************************************************/

static const struct bt_gatt_attr_s g_ai_attrs[] =
{
  /* Primary Service: AI Watch */

  BT_GATT_PRIMARY_SERVICE(AI_WATCH_BLE_HDL_SVC, &g_ai_svc_uuid),

  /* Status Characteristic: readable + notify */

  BT_GATT_CHARACTERISTIC(AI_WATCH_BLE_HDL_STATUS_CHR,
                         &g_status_chrc),
  BT_GATT_DESCRIPTOR(AI_WATCH_BLE_HDL_STATUS_VAL,
                     &g_ai_status_uuid,
                     BT_GATT_PERM_READ,
                     ai_ble_read_status, NULL, NULL),
  BT_GATT_CCC(AI_WATCH_BLE_HDL_STATUS_CCC,
              AI_WATCH_BLE_HDL_STATUS_VAL,
              g_status_ccc_cfg,
              ai_ble_status_ccc_changed),

  /* Time Sync Characteristic: writable */

  BT_GATT_CHARACTERISTIC(AI_WATCH_BLE_HDL_TIMESYNC_CHR,
                         &g_timesync_chrc),
  BT_GATT_DESCRIPTOR(AI_WATCH_BLE_HDL_TIMESYNC_VAL,
                     &g_ai_timesync_uuid,
                     BT_GATT_PERM_WRITE,
                     NULL, ai_ble_write_timesync, NULL),

  /* Data Upload Characteristic: notify only */

  BT_GATT_CHARACTERISTIC(AI_WATCH_BLE_HDL_DATA_CHR,
                         &g_dataupload_chrc),
  BT_GATT_DESCRIPTOR(AI_WATCH_BLE_HDL_DATA_VAL,
                     &g_ai_dataupload_uuid,
                     BT_GATT_PERM_READ,
                     NULL, NULL, NULL),
  BT_GATT_CCC(AI_WATCH_BLE_HDL_DATA_CCC,
              AI_WATCH_BLE_HDL_DATA_VAL,
              g_data_ccc_cfg,
              ai_ble_data_ccc_changed),
};

/****************************************************************************
 * Private Functions - BLE Interface Helpers
 ****************************************************************************/

/****************************************************************************
 * Name: ai_ble_get_info
 *
 * Description:
 *   Get BT interface info via SIOCGBTINFO ioctl.
 *
 * Returned Value:
 *   0 on success, negative errno on failure.
 *
 ****************************************************************************/

static int ai_ble_get_info(FAR struct btreq_s *btreq)
{
  int sockfd;
  int ret;

  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
  if (sockfd < 0)
    {
      return -errno;
    }

  memset(btreq, 0, sizeof(*btreq));
  strlcpy(btreq->btr_name, BLE_BTDEV_NAME, IFNAMSIZ);

  ret = ioctl(sockfd, SIOCGBTINFO,
              (unsigned long)((uintptr_t)btreq));
  close(sockfd);

  return ret < 0 ? -errno : 0;
}

/****************************************************************************
 * Name: ai_ble_start_advertising
 *
 * Description:
 *   Start BLE advertising via SIOCBTADVSTART ioctl.
 *
 * Returned Value:
 *   0 on success, negative errno on failure.
 *
 ****************************************************************************/

static int ai_ble_start_advertising(void)
{
  struct btreq_s btreq;
  int sockfd;
  int ret;

  memset(&btreq, 0, sizeof(btreq));
  strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
  btreq.btr_advtype = BT_LE_ADV_IND;

  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
  if (sockfd < 0)
    {
      printf("BLE: Socket create failed: %d\n", errno);
      return -errno;
    }

  ret = ioctl(sockfd, SIOCBTADVSTART,
              (unsigned long)((uintptr_t)&btreq));
  close(sockfd);

  if (ret < 0)
    {
      printf("BLE: SIOCBTADVSTART failed: %d\n", errno);
      return -errno;
    }

  printf("BLE: Advertising started\n");
  return 0;
}

/****************************************************************************
 * Private Functions - BLE Thread
 ****************************************************************************/

/****************************************************************************
 * Name: ai_ble_thread
 *
 * Description:
 *   Background thread that initializes BLE, registers the GATT service,
 *   and starts advertising. After initialization, enters a polling loop
 *   to detect connection state changes and restart advertising if needed.
 *
 ****************************************************************************/

static int ai_ble_thread(int argc, FAR char *argv[])
{
  FAR struct ai_watch_ble_state_s *ble;
  struct btreq_s btreq;
  int retry;
  int ret;

  /* Use the static global set by ai_watch_ble_init */

  ble = g_ble;
  if (ble == NULL)
    {
      printf("BLE: NULL state pointer\n");
      return -EINVAL;
    }

  printf("BLE: Thread started, waiting for interface...\n");

  /* Step 1: Wait for the BT network interface to appear.
   * The BLE stack auto-starts advertising when the interface comes up,
   * using CONFIG_DEVICE_LOCAL_NAME for the scan response name.
   */

  for (retry = 0; retry < BLE_IFACE_POLL_MAX; retry++)
    {
      ret = ai_ble_get_info(&btreq);
      if (ret == 0)
        {
          printf("BLE: Interface %s ready after %d ms\n",
                 BLE_BTDEV_NAME, retry * BLE_IFACE_POLL_MS);
          break;
        }

      usleep(BLE_IFACE_POLL_MS * 1000);
    }

  if (retry >= BLE_IFACE_POLL_MAX)
    {
      ble->state = BLE_STATE_INIT_FAILED;
      printf("BLE: Init failed — interface timeout\n");
      return -ETIMEDOUT;
    }

  /* Step 2: Register custom GATT service.
   * This adds our service to the BLE stack's attribute database.
   * The stack's auto-started advertising will include this service.
   */

  bt_gatt_register(g_ai_attrs, nitems(g_ai_attrs));
  printf("BLE: GATT service registered (attrs=%d)\n",
         (int)nitems(g_ai_attrs));

  /* Step 3: Explicitly (re)start advertising to ensure our custom
   * service is included in the advertising data.
   */

  ret = ai_ble_start_advertising();
  if (ret < 0)
    {
      /* Advertising may already be running from auto-start;
       * this is not necessarily a fatal error.
       */

      printf("BLE: Advertising start returned %d (may already "
             "be running)\n", ret);
    }

  ble->state = BLE_STATE_ADVERTISING;
  ble->initialized = true;
  printf("BLE: Initialization complete, advertising as %s\n",
         AI_WATCH_BLE_DEVICE_NAME);

  /* Step 4: Polling loop — check interface status periodically.
   * Detect connection state changes and restart advertising if needed.
   * This thread runs at low priority and sleeps between checks.
   *
   * NOTE: Without CONFIG_WIRELESS_BLUETOOTH_HOST, we cannot use
   * bt_conn_cb_register for connection callbacks. Instead, we poll
   * the interface flags via SIOCGBTINFO.
   *
   * The initial connection detection is best-effort: we detect when
   * the interface changes state and update the UI accordingly.
   * The GATT write callback for time sync works regardless of our
   * connection tracking since it's handled by the BLE stack.
   */

  for (; ; )
    {
      enum ai_watch_ble_state_e prev_state = ble->state;

      usleep(2000000); /* Check every 2 seconds */

      ret = ai_ble_get_info(&btreq);
      if (ret < 0)
        {
          if (prev_state != BLE_STATE_INIT_FAILED)
            {
              printf("BLE: Interface query failed: %d\n", ret);
              ble->state = BLE_STATE_INIT_FAILED;
            }

          continue;
        }

      /* Check if the interface is still running.
       * BTF_RUNNING (0x02) indicates the interface is operational.
       * If the interface is up but was previously failed/disconnected,
       * restart advertising.
       */

      if (!(btreq.btr_flags & BTF_RUNNING))
        {
          if (prev_state == BLE_STATE_CONNECTED ||
              prev_state == BLE_STATE_ADVERTISING)
            {
              printf("BLE: Interface down (flags=0x%04x), "
                     "restarting\n", btreq.btr_flags);
              ble->state = BLE_STATE_DISCONNECTED;

              /* Try to restart advertising */

              ai_ble_start_advertising();
            }
          else if (prev_state != BLE_STATE_DISCONNECTED)
            {
              ble->state = BLE_STATE_DISCONNECTED;
            }
        }
      else
        {
          /* Interface is running. If we were disconnected or
           * failed, go back to advertising.
           */

          if (prev_state == BLE_STATE_DISCONNECTED ||
              prev_state == BLE_STATE_INIT_FAILED)
            {
              printf("BLE: Interface recovered, "
                     "restarting advertising\n");
              ai_ble_start_advertising();
              ble->state = BLE_STATE_ADVERTISING;
            }
          else if (prev_state == BLE_STATE_OFF)
            {
              ble->state = BLE_STATE_ADVERTISING;
            }
        }
    }

  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: ai_watch_ble_init
 ****************************************************************************/

int ai_watch_ble_init(FAR struct ai_watch_ble_state_s *ble_state)
{
  int ret;

  if (ble_state == NULL)
    {
      return -EINVAL;
    }

  memset(ble_state, 0, sizeof(*ble_state));
  ble_state->state = BLE_STATE_OFF;

  /* Set global before thread starts — thread reads it immediately */

  g_ble = ble_state;

  ret = task_create("ai_ble", BLE_THREAD_PRIORITY,
                    BLE_THREAD_STACKSIZE, ai_ble_thread,
                    NULL);
  if (ret < 0)
    {
      int errcode = errno;

      printf("ERROR: BLE thread create failed: %d\n", errcode);
      ble_state->state = BLE_STATE_INIT_FAILED;
      return -errcode;
    }

  printf("BLE: Thread launched (pid=%d)\n", ret);
  return 0;
}

/****************************************************************************
 * Name: ai_watch_ble_update
 ****************************************************************************/

void ai_watch_ble_update(FAR struct ai_watch_ble_state_s *ble_state)
{
  struct timespec ts;
  struct tm tm;

  if (ble_state == NULL || !ble_state->timesync_pending)
    {
      return;
    }

  /* Process pending time sync — this runs in the main/LVGL thread */

  ble_state->timesync_pending = false;

  /* Set system time using clock_settime.
   * The received UTC seconds are stored directly; timezone offset
   * is noted but the system clock runs in UTC.
   */

  ts.tv_sec = (time_t)ble_state->pending_sync.utc_seconds;
  ts.tv_nsec = 0;

  if (clock_settime(CLOCK_REALTIME, &ts) < 0)
    {
      printf("BLE: clock_settime failed: %d\n", errno);
      return;
    }

  ble_state->last_sync_time = ts.tv_sec;

  if (localtime_r(&ts.tv_sec, &tm) != NULL)
    {
      printf("BLE: Time synced: %04d-%02d-%02d %02d:%02d:%02d "
             "(tz=%+d min)\n",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec,
             ble_state->pending_sync.tz_offset_min);
    }
}

/****************************************************************************
 * Name: ai_watch_ble_get_status_text
 ****************************************************************************/

FAR const char *ai_watch_ble_get_status_text(
    enum ai_watch_ble_state_e state)
{
  switch (state)
    {
      case BLE_STATE_OFF:
        return "BLE: OFF";
      case BLE_STATE_INIT_FAILED:
        return "BLE: ERR";
      case BLE_STATE_ADVERTISING:
        return "BLE: ADV";
      case BLE_STATE_CONNECTED:
        return "BLE: ON";
      case BLE_STATE_DISCONNECTED:
        return "BLE: LOST";
      default:
        return "BLE: ???";
    }
}

