 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#include "ai_watch_ble.h"

/****************************************************************************
 * BLE Host Stack Detection
 *
 * The NuttX native BLE host stack (CONFIG_WIRELESS_BLUETOOTH) is required
 * for GATT server, advertising, and connection management.
 * Without it, BLE shows INIT_FAILED status.
 *
 * The SiFli BSP uses zblue (Zephyr-based) BLE stack, but its headers
 * are not directly includable from NuttX user applications.
 * Enabling CONFIG_WIRELESS_BLUETOOTH provides the NuttX native BLE
 * host stack which coexists with the SiFli HCI transport.
 ****************************************************************************/

#ifdef CONFIG_WIRELESS_BLUETOOTH

/****************************************************************************
 * BLE Host Stack Available — Full Implementation
 ****************************************************************************/

#include <fcntl.h>
#include <unistd.h>

#include <arpa/inet.h>
#include <netpacket/bluetooth.h>
#include <sys/ioctl.h>
#include <sys/socket.h>

#include <nuttx/wireless/bluetooth/bt_core.h>
#include <nuttx/wireless/bluetooth/bt_gatt.h>
#include <nuttx/wireless/bluetooth/bt_hci.h>
#include <nuttx/wireless/bluetooth/bt_ioctl.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BLE_THREAD_STACKSIZE    4096
#define BLE_THREAD_PRIORITY     110
#define BLE_IFACE_POLL_MS       500
#define BLE_IFACE_POLL_MAX      60  /* 30 seconds max wait */
#define BLE_BTDEV_NAME          "bnep0"

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct bt_gatt_ccc_cfg_s g_status_ccc_cfg[1];
static struct bt_gatt_ccc_cfg_s g_data_ccc_cfg[1];
static FAR struct ai_watch_ble_state_s *g_ble;

/* Custom GATT Service UUIDs */

static struct bt_uuid_s g_ai_svc_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_SVC_UUID128,
};

static struct bt_uuid_s g_ai_status_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_STATUS_UUID128,
};

static struct bt_uuid_s g_ai_timesync_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_TIMESYNC_UUID128,
};

static struct bt_uuid_s g_ai_dataupload_uuid =
{
  .type = BT_UUID_128,
  .u.u128 = AI_WATCH_BLE_DATAUPLOAD_UUID128,
};

/* Characteristic declarations */

static struct bt_gatt_chrc_s g_status_chrc =
{
  .properties = BT_GATT_CHRC_READ | BT_GATT_CHRC_NOTIFY,
  .value_handle = AI_WATCH_BLE_HDL_STATUS_VAL,
  .uuid = &g_ai_status_uuid,
};

static struct bt_gatt_chrc_s g_timesync_chrc =
{
  .properties = BT_GATT_CHRC_WRITE,
  .value_handle = AI_WATCH_BLE_HDL_TIMESYNC_VAL,
  .uuid = &g_ai_timesync_uuid,
};

static struct bt_gatt_chrc_s g_dataupload_chrc =
{
  .properties = BT_GATT_CHRC_NOTIFY,
  .value_handle = AI_WATCH_BLE_HDL_DATA_VAL,
  .uuid = &g_ai_dataupload_uuid,
};

/****************************************************************************
 * Private Functions - GATT Callbacks
 ****************************************************************************/

static int ai_ble_read_status(FAR struct bt_conn_s *conn,
                              FAR const struct bt_gatt_attr_s *attr,
                              FAR void *buf, uint8_t len, uint16_t offset)
{
  uint8_t status[AI_WATCH_BLE_STATUS_SIZE];
  time_t sync;

  status[0] = AI_WATCH_BLE_PROTOCOL_VERSION;
  status[1] = (g_ble != NULL && g_ble->state == BLE_STATE_CONNECTED) ?
               1 : 0;
  sync = (g_ble != NULL) ? g_ble->last_sync_time : 0;
  memcpy(&status[2], &sync, 4);

  return bt_gatt_attr_read(conn, attr, buf, len, offset,
                           status, sizeof(status));
}

static int ai_ble_write_timesync(FAR struct bt_conn_s *conn,
                                 FAR const struct bt_gatt_attr_s *attr,
                                 FAR const void *buf, uint8_t len,
                                 uint16_t offset)
{
  FAR const uint8_t *data = buf;
  struct ai_watch_ble_timesync_s sync;

  if (len != AI_WATCH_BLE_TIMESYNC_SIZE)
    {
      printf("BLE: TimeSync rejected: bad len %u\n", len);
      return -EINVAL;
    }

  if (data[0] != AI_WATCH_BLE_PROTOCOL_VERSION)
    {
      printf("BLE: TimeSync rejected: version %u\n", data[0]);
      return -EINVAL;
    }

  sync.version = data[0];
  memcpy(&sync.utc_seconds, &data[1], 4);
  memcpy(&sync.tz_offset_min, &data[5], 2);

  if (sync.utc_seconds < 1577836800u || sync.utc_seconds > 4102444800u)
    {
      printf("BLE: TimeSync rejected: UTC out of range\n");
      return -EINVAL;
    }

  if (sync.tz_offset_min < -720 || sync.tz_offset_min > 840)
    {
      printf("BLE: TimeSync rejected: tz out of range\n");
      return -EINVAL;
    }

  if (g_ble == NULL)
    {
      return -EFAULT;
    }

  memcpy(&g_ble->pending_sync, &sync, sizeof(sync));
  g_ble->timesync_pending = true;
  printf("BLE: TimeSync accepted: UTC=%lu tz=%d\n",
         (unsigned long)sync.utc_seconds, sync.tz_offset_min);
  return len;
}

static void ai_ble_status_ccc_changed(uint16_t value)
{
  printf("BLE: Status CCC: 0x%04x\n", value);
}

static void ai_ble_data_ccc_changed(uint16_t value)
{
  printf("BLE: Data CCC: 0x%04x\n", value);
}

/* GATT attribute table */

static const struct bt_gatt_attr_s g_ai_attrs[] =
{
  BT_GATT_PRIMARY_SERVICE(AI_WATCH_BLE_HDL_SVC, &g_ai_svc_uuid),
  BT_GATT_CHARACTERISTIC(AI_WATCH_BLE_HDL_STATUS_CHR, &g_status_chrc),
  BT_GATT_DESCRIPTOR(AI_WATCH_BLE_HDL_STATUS_VAL, &g_ai_status_uuid,
                     BT_GATT_PERM_READ, ai_ble_read_status, NULL, NULL),
  BT_GATT_CCC(AI_WATCH_BLE_HDL_STATUS_CCC, AI_WATCH_BLE_HDL_STATUS_VAL,
              g_status_ccc_cfg, ai_ble_status_ccc_changed),
  BT_GATT_CHARACTERISTIC(AI_WATCH_BLE_HDL_TIMESYNC_CHR, &g_timesync_chrc),
  BT_GATT_DESCRIPTOR(AI_WATCH_BLE_HDL_TIMESYNC_VAL, &g_ai_timesync_uuid,
                     BT_GATT_PERM_WRITE, NULL, ai_ble_write_timesync,
                     NULL),
  BT_GATT_CHARACTERISTIC(AI_WATCH_BLE_HDL_DATA_CHR, &g_dataupload_chrc),
  BT_GATT_DESCRIPTOR(AI_WATCH_BLE_HDL_DATA_VAL, &g_ai_dataupload_uuid,
                     BT_GATT_PERM_READ, NULL, NULL, NULL),
  BT_GATT_CCC(AI_WATCH_BLE_HDL_DATA_CCC, AI_WATCH_BLE_HDL_DATA_VAL,
              g_data_ccc_cfg, ai_ble_data_ccc_changed),
};

/****************************************************************************
 * Private Functions - BLE Thread
 ****************************************************************************/

static int ai_ble_get_info(FAR struct btreq_s *btreq)
{
  int sockfd;
  int ret;

  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
  if (sockfd < 0)
    {
      return -errno;
    }

  memset(btreq, 0, sizeof(*btreq));
  strlcpy(btreq->btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
  ret = ioctl(sockfd, SIOCGBTINFO,
              (unsigned long)((uintptr_t)btreq));
  close(sockfd);
  return ret < 0 ? -errno : 0;
}

static int ai_ble_start_advertising(void)
{
  struct btreq_s btreq;
  int sockfd;
  int ret;

  memset(&btreq, 0, sizeof(btreq));
  strlcpy(btreq.btr_name, BLE_BTDEV_NAME, IFNAMSIZ);
  btreq.btr_advtype = BT_LE_ADV_IND;

  sockfd = socket(PF_BLUETOOTH, SOCK_RAW, BTPROTO_L2CAP);
  if (sockfd < 0)
    {
      return -errno;
    }

  ret = ioctl(sockfd, SIOCBTADVSTART,
              (unsigned long)((uintptr_t)&btreq));
  close(sockfd);
  return ret < 0 ? -errno : 0;
}

static int ai_ble_thread(int argc, FAR char *argv[])
{
  FAR struct ai_watch_ble_state_s *ble = g_ble;
  struct btreq_s btreq;
  int retry;
  int ret;

  if (ble == NULL)
    {
      return -EINVAL;
    }

  printf("BLE: Thread started\n");

  for (retry = 0; retry < BLE_IFACE_POLL_MAX; retry++)
    {
      ret = ai_ble_get_info(&btreq);
      if (ret == 0)
        {
          printf("BLE: Interface ready after %d ms\n",
                 retry * BLE_IFACE_POLL_MS);
          break;
        }

      usleep(BLE_IFACE_POLL_MS * 1000);
    }

  if (retry >= BLE_IFACE_POLL_MAX)
    {
      ble->state = BLE_STATE_INIT_FAILED;
      printf("BLE: Init failed — interface timeout\n");
      return -ETIMEDOUT;
    }

  bt_gatt_register(g_ai_attrs, nitems(g_ai_attrs));
  printf("BLE: GATT service registered\n");

  ret = ai_ble_start_advertising();
  if (ret < 0)
    {
      printf("BLE: Adv start returned %d\n", ret);
    }

  ble->state = BLE_STATE_ADVERTISING;
  ble->initialized = true;
  printf("BLE: Advertising as %s\n", AI_WATCH_BLE_DEVICE_NAME);

  for (; ; )
    {
      usleep(2000000);
      ret = ai_ble_get_info(&btreq);
      if (ret < 0)
        {
          if (ble->state != BLE_STATE_INIT_FAILED)
            {
              ble->state = BLE_STATE_INIT_FAILED;
            }
          continue;
        }

      if (!(btreq.btr_flags & BTF_RUNNING))
        {
          if (ble->state == BLE_STATE_CONNECTED)
            {
              ble->state = BLE_STATE_DISCONNECTED;
            }

          ai_ble_start_advertising();
          ble->state = BLE_STATE_ADVERTISING;
        }
      else if (ble->state == BLE_STATE_OFF ||
               ble->state == BLE_STATE_INIT_FAILED ||
               ble->state == BLE_STATE_DISCONNECTED)
        {
          ble->state = BLE_STATE_ADVERTISING;
        }
    }

  return 0;
}

int ai_watch_ble_init(FAR struct ai_watch_ble_state_s *ble_state)
{
  int ret;

  if (ble_state == NULL)
    {
      return -EINVAL;
    }

  memset(ble_state, 0, sizeof(*ble_state));
  ble_state->state = BLE_STATE_OFF;
  g_ble = ble_state;

  ret = task_create("ai_ble", BLE_THREAD_PRIORITY,
                    BLE_THREAD_STACKSIZE, ai_ble_thread, NULL);
  if (ret < 0)
    {
      ble_state->state = BLE_STATE_INIT_FAILED;
      return -errno;
    }

