/****************************************************************************
 * BLE Stack Integration
 *
 * The SF32LB52 BSP uses zblue (Zephyr BLE stack) for BLE host.
 * The NuttX native BLE host stack (CONFIG_WIRELESS_BLUETOOTH) is NOT
 * available — its Kconfig is not sourced by the build system.
 *
 * We use a weak hook in the BSP (sf32lb52_bt_register_custom_services)
 * to register custom GATT services after zblue initialization.
 * The zblue API functions are declared locally since the Zephyr headers
 * cannot be included directly from NuttX user applications.
 ****************************************************************************/

/****************************************************************************
 * zblue API Declarations
 *
 * These match the zblue library's symbol signatures. The structures
 * must have the exact same layout as the library expects.
 ****************************************************************************/

/* Forward declarations for zblue types */

struct bt_dev;
struct bt_conn;

/* Linked list node — matches zblue's sys_snode_t (struct _snode) */

struct zblue_snode
{
  struct zblue_snode *next;
};

/* UUID types — matches zblue's struct bt_uuid */

struct zblue_uuid
{
  uint8_t type;
  union
  {
    uint16_t u16;
    uint8_t  u128[16];
  } u;
};

/* UUID type constants */

#define ZBLUE_UUID_16   2
#define ZBLUE_UUID_128  4

/* GATT attribute — matches zblue's struct bt_gatt_attr */

typedef ssize_t (*zblue_attr_read_t)(struct bt_conn *conn,
                                     const struct zblue_gatt_attr *attr,
                                     void *buf, uint16_t len,
                                     uint16_t offset);

typedef ssize_t (*zblue_attr_write_t)(struct bt_conn *conn,
                                      const struct zblue_gatt_attr *attr,
                                      const void *buf, uint16_t len,
                                      uint16_t offset);

struct zblue_gatt_attr
{
  const struct zblue_uuid *uuid;
  zblue_attr_read_t read;
  zblue_attr_write_t write;
  void *user_data;
  uint16_t handle;
  uint8_t perm;
};

/* GATT service — matches zblue's struct bt_gatt_service */

struct zblue_gatt_service
{
  struct bt_dev *hdev;
  struct zblue_gatt_attr *attrs;
  size_t attr_count;
  struct zblue_snode node;
};

/* GATT characteristic properties */

#define ZBLUE_CHRC_READ         0x02
#define ZBLUE_CHRC_WRITE        0x08
#define ZBLUE_CHRC_NOTIFY       0x10

/* GATT permissions */

#define ZBLUE_PERM_READ         0x01
#define ZBLUE_PERM_WRITE        0x02

/* CCC callback type */

typedef void (*zblue_ccc_changed_t)(const struct zblue_gatt_attr *attr,
                                    uint16_t value);

/* CCC managed structure — matches zblue's struct _bt_gatt_ccc */

struct zblue_gatt_ccc
{
  struct zblue_gatt_ccc_cfg
  {
    struct bt_conn *conn;
    uint16_t value;
  } cfg[1];
  uint16_t value;
  uint16_t value_handle;
  zblue_ccc_changed_t changed;
  zblue_ccc_changed_t write;
  bool (*match)(const struct zblue_gatt_attr *attr);
};

/* Characteristic value structure — matches zblue's bt_gatt_chrc */

struct zblue_gatt_chrc
{
  const struct zblue_uuid *uuid;
  uint16_t value_handle;
  uint8_t properties;
};

/* External zblue API functions */

extern int bt_gatt_service_register_mc(uint8_t dev_id,
                                       struct zblue_gatt_service *svc);

extern ssize_t bt_gatt_attr_read_service(struct bt_conn *conn,
                                         const struct zblue_gatt_attr *attr,
                                         void *buf, uint16_t len,
                                         uint16_t offset);

extern ssize_t bt_gatt_attr_read_chrc(struct bt_conn *conn,
                                      const struct zblue_gatt_attr *attr,
                                      void *buf, uint16_t len,
                                      uint16_t offset);

extern ssize_t bt_gatt_attr_read(struct bt_conn *conn,
                                 const struct zblue_gatt_attr *attr,
                                 void *buf, uint16_t len, uint16_t offset,
                                 const void *value, uint16_t value_len);

extern ssize_t bt_gatt_attr_write_ccc(struct bt_conn *conn,
                                      const struct zblue_gatt_attr *attr,
                                      const void *buf, uint16_t len,
                                      uint16_t offset);

extern ssize_t bt_gatt_attr_read_ccc(struct bt_conn *conn,
                                     const struct zblue_gatt_attr *attr,
                                     void *buf, uint16_t len,
                                     uint16_t offset);

/****************************************************************************
 * Pre-processor Definitions — zblue GATT macros
 *
 * We replicate the zblue BT_GATT_* macros locally since we can't include
 * the Zephyr headers.
 ****************************************************************************/

#define ZBLUE_BT_GATT_ATTRIBUTE(_uuid, _perm, _read, _write, _udata) \
  { \
    .uuid = _uuid, \
    .read = (zblue_attr_read_t)_read, \
    .write = (zblue_attr_write_t)_write, \
    .user_data = _udata, \
    .handle = 0, \
    .perm = _perm, \
  }

#define ZBLUE_BT_GATT_PRIMARY_SERVICE(_service) \
  ZBLUE_BT_GATT_ATTRIBUTE(&g_zblue_gatt_primary_uuid, ZBLUE_PERM_READ, \
                           bt_gatt_attr_read_service, NULL, \
                           (void *)_service)

#define ZBLUE_BT_GATT_CHARACTERISTIC(_uuid, _props, _read, _write, _udata) \
  ZBLUE_BT_GATT_ATTRIBUTE(&g_zblue_gatt_chrc_uuid, ZBLUE_PERM_READ, \
                           bt_gatt_attr_read_chrc, NULL, \
                           (&(struct zblue_gatt_chrc){ \
                             .uuid = _uuid, \
                             .value_handle = 0, \
                             .properties = _props, \
                           })), \
  ZBLUE_BT_GATT_ATTRIBUTE(_uuid, \
                           ((_props & ZBLUE_CHRC_READ) ? \
                             ZBLUE_PERM_READ : 0) | \
                           ((_props & ZBLUE_CHRC_WRITE) ? \
                             ZBLUE_PERM_WRITE : 0), \
                           _read, _write, _udata)

#define ZBLUE_BT_GATT_CCC(_ccc, _perm) \
  ZBLUE_BT_GATT_ATTRIBUTE(&g_zblue_gatt_ccc_uuid, _perm, \
                           bt_gatt_attr_read_ccc, \
                           bt_gatt_attr_write_ccc, _ccc)

/****************************************************************************
 * Private Data — UUID constants
 ****************************************************************************/

/* Standard BLE UUIDs */

static const struct zblue_uuid g_zblue_gatt_primary_uuid =
{
  .type = ZBLUE_UUID_16,
  .u.u16 = 0x2800,
};

static const struct zblue_uuid g_zblue_gatt_chrc_uuid =
{
  .type = ZBLUE_UUID_16,
  .u.u16 = 0x2803,
};

static const struct zblue_uuid g_zblue_gatt_ccc_uuid =
{
  .type = ZBLUE_UUID_16,
  .u.u16 = 0x2902,
};

/* Custom 128-bit service UUID */

static const struct zblue_uuid g_ai_svc_uuid =
{
  .type = ZBLUE_UUID_128,
  .u.u128 = AI_WATCH_BLE_SVC_UUID128,
};

static const struct zblue_uuid g_ai_status_uuid =
{
  .type = ZBLUE_UUID_128,
  .u.u128 = AI_WATCH_BLE_STATUS_UUID128,
};

static const struct zblue_uuid g_ai_timesync_uuid =
{
  .type = ZBLUE_UUID_128,
  .u.u128 = AI_WATCH_BLE_TIMESYNC_UUID128,
};

static const struct zblue_uuid g_ai_dataupload_uuid =
{
  .type = ZBLUE_UUID_128,
  .u.u128 = AI_WATCH_BLE_DATAUPLOAD_UUID128,
};

/****************************************************************************
 * Private Data — BLE State and CCC
 ****************************************************************************/

static struct ai_watch_ble_state_s g_ble_state;
static struct zblue_gatt_ccc g_status_ccc;
static struct zblue_gatt_ccc g_data_ccc;

/****************************************************************************
 * Private Functions — GATT Callbacks
 ****************************************************************************/

static ssize_t ai_ble_read_status(struct bt_conn *conn,
                                  const struct zblue_gatt_attr *attr,
                                  void *buf, uint16_t len, uint16_t offset)
{
  uint8_t status[AI_WATCH_BLE_STATUS_SIZE];
  time_t sync;

  status[0] = AI_WATCH_BLE_PROTOCOL_VERSION;
  status[1] = (g_ble_state.state == BLE_STATE_CONNECTED) ? 1 : 0;
  sync = g_ble_state.last_sync_time;
  memcpy(&status[2], &sync, 4);

  return bt_gatt_attr_read(conn, attr, buf, len, offset,
                           status, sizeof(status));
}

static ssize_t ai_ble_write_timesync(struct bt_conn *conn,
                                     const struct zblue_gatt_attr *attr,
                                     const void *buf, uint16_t len,
                                     uint16_t offset)
{
  const uint8_t *data = buf;
  struct ai_watch_ble_timesync_s sync;

  if (len != AI_WATCH_BLE_TIMESYNC_SIZE)
    {
      printf("BLE: TimeSync rejected: bad len %u\n", len);
      return -EINVAL;
    }

  if (data[0] != AI_WATCH_BLE_PROTOCOL_VERSION)
    {
      printf("BLE: TimeSync rejected: version %u\n", data[0]);
      return -EINVAL;
    }

  sync.version = data[0];
  memcpy(&sync.utc_seconds, &data[1], 4);
  memcpy(&sync.tz_offset_min, &data[5], 2);

  if (sync.utc_seconds < 1577836800u || sync.utc_seconds > 4102444800u)
    {
      printf("BLE: TimeSync rejected: UTC out of range\n");
      return -EINVAL;
    }

  if (sync.tz_offset_min < -720 || sync.tz_offset_min > 840)
    {
      printf("BLE: TimeSync rejected: tz out of range\n");
      return -EINVAL;
    }

  memcpy(&g_ble_state.pending_sync, &sync, sizeof(sync));
  g_ble_state.timesync_pending = true;
  printf("BLE: TimeSync accepted: UTC=%lu tz=%d\n",
         (unsigned long)sync.utc_seconds, sync.tz_offset_min);
  return len;
}

static void ai_ble_status_ccc_changed(const struct zblue_gatt_attr *attr,
                                      uint16_t value)
{
  printf("BLE: Status CCC changed: 0x%04x\n", value);
  if (value & 0x0001)
    {
      g_ble_state.state = BLE_STATE_CONNECTED;
    }
}

static void ai_ble_data_ccc_changed(const struct zblue_gatt_attr *attr,
                                    uint16_t value)
{
  printf("BLE: Data CCC changed: 0x%04x\n", value);
}

/****************************************************************************
 * Private Data — GATT Attribute Table
 ****************************************************************************/

static struct zblue_gatt_attr g_ai_attrs[] =
{
  /* Primary Service */

  ZBLUE_BT_GATT_PRIMARY_SERVICE(&g_ai_svc_uuid),

  /* Status: Read + Notify */

  ZBLUE_BT_GATT_CHARACTERISTIC(&g_ai_status_uuid,
                                ZBLUE_CHRC_READ | ZBLUE_CHRC_NOTIFY,
                                ai_ble_read_status, NULL, NULL),

  /* TimeSync: Write */

  ZBLUE_BT_GATT_CHARACTERISTIC(&g_ai_timesync_uuid,
                                ZBLUE_CHRC_WRITE,
                                NULL, ai_ble_write_timesync, NULL),

  /* DataUpload: Notify */

  ZBLUE_BT_GATT_CHARACTERISTIC(&g_ai_dataupload_uuid,
                                ZBLUE_CHRC_NOTIFY,
                                NULL, NULL, NULL),
};

/* CCC descriptors for notify characteristics — placed after attrs */

static struct zblue_gatt_attr g_ai_ccc_attrs[] =
{
  ZBLUE_BT_GATT_CCC(&g_status_ccc, ZBLUE_PERM_READ | ZBLUE_PERM_WRITE),
  ZBLUE_BT_GATT_CCC(&g_data_ccc, ZBLUE_PERM_READ | ZBLUE_PERM_WRITE),
};

static struct zblue_gatt_service g_ai_service =
{
  .hdev = NULL,
  .attrs = g_ai_attrs,
  .attr_count = sizeof(g_ai_attrs) / sizeof(g_ai_attrs[0]),
  .node = { NULL },
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sf32lb52_bt_register_custom_services
 *
 * Description:
 *   BSP hook — called after zblue initialization to register custom
 *   GATT services. This is a strong override of the weak symbol in
 *   sf32lb52_bth4.c.
 *
 ****************************************************************************/

void sf32lb52_bt_register_custom_services(void)
{
  int ret;

  /* Initialize CCC structures */

  memset(&g_status_ccc, 0, sizeof(g_status_ccc));
  g_status_ccc.changed = ai_ble_status_ccc_changed;
  memset(&g_data_ccc, 0, sizeof(g_data_ccc));
  g_data_ccc.changed = ai_ble_data_ccc_changed;

  ret = bt_gatt_service_register_mc(0, &g_ai_service);
  if (ret < 0)
    {
      printf("BLE: GATT service register failed: %d\n", ret);
      g_ble_state.state = BLE_STATE_INIT_FAILED;
      return;
    }

  g_ble_state.state = BLE_STATE_ADVERTISING;
  g_ble_state.initialized = true;
  printf("BLE: Custom GATT service registered, advertising as %s\n",
         AI_WATCH_BLE_DEVICE_NAME);
}

/****************************************************************************
 * Name: ai_watch_ble_init
 ****************************************************************************/

int ai_watch_ble_init(FAR struct ai_watch_ble_state_s *ble_state)
{
  if (ble_state == NULL)
    {
      return -EINVAL;
    }

  /* Copy the global state (set by the BSP hook) to the caller's struct */

  memcpy(ble_state, &g_ble_state, sizeof(*ble_state));

  printf("BLE: Init, state=%d\n", ble_state->state);
  return 0;
}

/****************************************************************************
 * Name: ai_watch_ble_update
 ****************************************************************************/

void ai_watch_ble_update(FAR struct ai_watch_ble_state_s *ble_state)
{
  struct timespec ts;
  struct tm tm;

  if (ble_state == NULL || !g_ble_state.timesync_pending)
    {
      return;
    }

  g_ble_state.timesync_pending = false;

  ts.tv_sec = (time_t)g_ble_state.pending_sync.utc_seconds;
  ts.tv_nsec = 0;

  if (clock_settime(CLOCK_REALTIME, &ts) < 0)
    {
      printf("BLE: clock_settime failed: %d\n", errno);
      return;
    }

  g_ble_state.last_sync_time = ts.tv_sec;
  ble_state->last_sync_time = ts.tv_sec;

  if (localtime_r(&ts.tv_sec, &tm) != NULL)
    {
      printf("BLE: Time synced: %04d-%02d-%02d %02d:%02d:%02d "
             "(tz=%+d min)\n",
             tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec,
             g_ble_state.pending_sync.tz_offset_min);
    }
}

