static ssize_t ai_ble_write_command(struct bt_conn *conn,
                                    const struct zblue_gatt_attr *attr,
                                    const void *buf, uint16_t len,
                                    uint16_t offset)
{
  const uint8_t *data = buf;
  uint8_t version;
  uint8_t cmd_type;
  uint8_t item_id;
  uint8_t flags;
  uint8_t title_len;
  uint32_t timestamp;
  struct ai_watch_reminder_s *slot;
  int i;

  /* Minimum: version(1) + cmd_type(1) = 2 bytes */

  if (len < 2)
    {
      printf("BLE: Cmd rejected: too short (%u)\n", len);
      return -EINVAL;
    }

  version = data[0];
  cmd_type = data[1];

  if (version != AI_WATCH_BLE_PROTOCOL_VERSION)
    {
      printf("BLE: Cmd rejected: version %u\n", version);
      return -EINVAL;
    }

  switch (cmd_type)
    {
      case AI_WATCH_BLE_CMD_REMINDER:
        /* Payload: version(1) + type(1) + id(1) + flags(1) +
         * timestamp(4) + title_len(1) + title(N)
         * Minimum: 9 bytes
         */

        if (len < 9)
          {
            printf("BLE: Reminder rejected: too short\n");
            return -EINVAL;
          }

        item_id = data[2];
        flags = data[3];
        memcpy(&timestamp, &data[4], 4);
        title_len = data[8];

        if (title_len > AI_WATCH_REMINDER_TITLE_MAX)
          {
            title_len = AI_WATCH_REMINDER_TITLE_MAX;
          }

        if (len < 9u + title_len)
          {
            printf("BLE: Reminder rejected: title truncated\n");
            return -EINVAL;
          }

        /* Find existing slot or empty slot */

        slot = NULL;
        for (i = 0; i < AI_WATCH_REMINDER_MAX; i++)
          {
            if (g_reminders.items[i].id == item_id)
              {
                slot = &g_reminders.items[i];
                break;
              }
          }

        if (slot == NULL)
          {
            /* Find empty slot */

            for (i = 0; i < AI_WATCH_REMINDER_MAX; i++)
              {
                if (g_reminders.items[i].id == 0)
                  {
                    slot = &g_reminders.items[i];
                    g_reminders.count++;
                    break;
                  }
              }
          }

        if (slot == NULL)
          {
            printf("BLE: Reminder store full\n");
            return -ENOSPC;
          }

        slot->id = item_id;
        slot->flags = flags;
        slot->timestamp = timestamp;
        memcpy(slot->title, &data[9], title_len);
        slot->title[title_len] = '\0';
        g_reminders.pending = true;

        printf("BLE: Reminder[%u] = \"%s\" (flags=0x%02x)\n",
               item_id, slot->title, flags);
        break;

      case AI_WATCH_BLE_CMD_CLEAR:
        /* Clear all reminders */

        memset(&g_reminders, 0, sizeof(g_reminders));
        g_reminders.pending = true;
        printf("BLE: Reminders cleared\n");
        break;

      default:
        printf("BLE: Unknown cmd type: 0x%02x\n", cmd_type);
        return -EINVAL;
    }

  return len;
}

