/****************************************************************************
 * Name: ai_watch_ble_send_sensor_data
 *
 * Description:
 *   Send sensor data via the DataUpload characteristic notification.
 *   Data format: [version(1)] [sensor_type(1)] [payload(N)]
 *
 *   sensor_type:
 *     0x01 = temperature (float, 4 bytes)
 *     0x02 = humidity (float, 4 bytes)
 *     0x03 = heart rate (int16, 2 bytes)
 *     0x04 = spo2 (int16, 2 bytes)
 *
 ****************************************************************************/

int ai_watch_ble_send_sensor_data(uint8_t sensor_type,
                                  FAR const void *data,
                                  uint8_t data_len)
{
  struct zblue_gatt_notify_params params;
  uint8_t buf[16];
  int ret;

  if (g_active_conn == NULL || g_ble_state.state != BLE_STATE_CONNECTED)
    {
      return -ENOTCONN;
    }

  if (1 + 1 + data_len > sizeof(buf))
    {
      return -E2BIG;
    }

  buf[0] = AI_WATCH_BLE_PROTOCOL_VERSION;
  buf[1] = sensor_type;
  memcpy(&buf[2], data, data_len);

  memset(&params, 0, sizeof(params));
  params.uuid = (const struct zblue_uuid *)&g_ai_dataupload_uuid;
  params.attr = NULL;
  params.data = buf;
  params.len = 2 + data_len;
  params.func = NULL;
  params.user_data = NULL;

  ret = bt_gatt_notify_cb(g_active_conn, &params);
  if (ret < 0)
    {
      printf("BLE: Notify failed: %d\n", ret);
    }

  return ret;
}

