/****************************************************************************
 * vendor/sifli/chips/sf32lb52/sf32lb52_bt_gatt_custom.c
 *
 * Custom GATT service registration for AI Watch.
 * This file is compiled with the zblue include path, so it uses
 * the correct zblue struct definitions.
