#include <nuttx/config.h>

#include <stdio.h>
#include <string.h>

#include <zephyr/bluetooth/bluetooth.h>
#include <zephyr/bluetooth/gatt.h>
#include <zephyr/bluetooth/uuid.h>

/****************************************************************************
 * Custom 128-bit UUIDs for AI Watch service
 ****************************************************************************/

static struct bt_uuid_128 g_ai_svc_uuid =
  BT_UUID_INIT_128(
    0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12,
    0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12);

static struct bt_uuid_128 g_ai_status_uuid =
  BT_UUID_INIT_128(
    0xf1, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12,
    0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12);

static struct bt_uuid_128 g_ai_timesync_uuid =
  BT_UUID_INIT_128(
    0xf2, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12,
    0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12);

static struct bt_uuid_128 g_ai_dataupload_uuid =
  BT_UUID_INIT_128(
    0xf3, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12,
    0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12);

static struct bt_uuid_128 g_ai_command_uuid =
  BT_UUID_INIT_128(
    0xf4, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12,
    0xf0, 0xde, 0xbc, 0x9a, 0x78, 0x56, 0x34, 0x12);

/****************************************************************************
 * BLE Protocol Definitions
 ****************************************************************************/

#define BLE_PROTOCOL_VERSION  1
#define BLE_TIMESYNC_SIZE     7
#define BLE_STATUS_SIZE       6

/* Time sync state — shared with application */

struct ble_timesync_data_s
{
  volatile bool pending;
  uint32_t utc_seconds;
  int16_t tz_offset_min;
};

static struct ble_timesync_data_s g_timesync;

/* Connection state */

static volatile bool g_connected;

/****************************************************************************
 * GATT Callbacks
 ****************************************************************************/

static ssize_t read_status(struct bt_conn *conn,
                           const struct bt_gatt_attr *attr,
                           void *buf, uint16_t len, uint16_t offset)
{
  uint8_t status[BLE_STATUS_SIZE];
  time_t now;

  status[0] = BLE_PROTOCOL_VERSION;
  status[1] = g_connected ? 1 : 0;
  now = time(NULL);
  memcpy(&status[2], &now, 4);

  return bt_gatt_attr_read(conn, attr, buf, len, offset,
                           status, sizeof(status));
}

static ssize_t write_timesync(struct bt_conn *conn,
                              const struct bt_gatt_attr *attr,
                              const void *buf, uint16_t len,
                              uint16_t offset)
{
  const uint8_t *data = buf;

  if (len != BLE_TIMESYNC_SIZE)
    {
      printf("BLE: TimeSync rejected: bad len %u\n", len);
      return BT_GATT_ERR(BT_ATT_ERR_INVALID_ATTRIBUTE_LEN);
    }

  if (data[0] != BLE_PROTOCOL_VERSION)
    {
      printf("BLE: TimeSync rejected: version %u\n", data[0]);
      return BT_GATT_ERR(BT_ATT_ERR_VALUE_NOT_ALLOWED);
    }

  memcpy(&g_timesync.utc_seconds, &data[1], 4);
  memcpy(&g_timesync.tz_offset_min, &data[5], 2);

  /* Sanity checks */

  if (g_timesync.utc_seconds < 1577836800u ||
      g_timesync.utc_seconds > 4102444800u)
    {
      printf("BLE: TimeSync rejected: UTC out of range\n");
      return BT_GATT_ERR(BT_ATT_ERR_VALUE_NOT_ALLOWED);
    }

  if (g_timesync.tz_offset_min < -720 ||
      g_timesync.tz_offset_min > 840)
    {
      printf("BLE: TimeSync rejected: tz out of range\n");
      return BT_GATT_ERR(BT_ATT_ERR_VALUE_NOT_ALLOWED);
    }

  g_timesync.pending = true;
  printf("BLE: TimeSync accepted: UTC=%lu tz=%d\n",
         (unsigned long)g_timesync.utc_seconds,
         g_timesync.tz_offset_min);
  return len;
}

static void status_ccc_changed(const struct bt_gatt_attr *attr,
                               uint16_t value)
{
  g_connected = (value & BT_GATT_CCC_NOTIFY) != 0;
  printf("BLE: Status CCC: 0x%04x (connected=%d)\n",
         value, g_connected);
}

static void data_ccc_changed(const struct bt_gatt_attr *attr,
                             uint16_t value)
{
  printf("BLE: Data CCC: 0x%04x\n", value);
}

/****************************************************************************
 * GATT Attribute Table
 ****************************************************************************/

BT_GATT_SERVICE_DEFINE(g_ai_svc,
  BT_GATT_PRIMARY_SERVICE(&g_ai_svc_uuid),

  /* Status: Read + Notify */

  BT_GATT_CHARACTERISTIC(&g_ai_status_uuid.uuid,
                         BT_GATT_CHRC_READ | BT_GATT_CHRC_NOTIFY,
                         BT_GATT_PERM_READ,
                         read_status, NULL, NULL),
  BT_GATT_CCC(status_ccc_changed,
              BT_GATT_PERM_READ | BT_GATT_PERM_WRITE),

  /* TimeSync: Write */

  BT_GATT_CHARACTERISTIC(&g_ai_timesync_uuid.uuid,
                         BT_GATT_CHRC_WRITE,
                         BT_GATT_PERM_WRITE,
                         NULL, write_timesync, NULL),

  /* DataUpload: Notify */

  BT_GATT_CHARACTERISTIC(&g_ai_dataupload_uuid.uuid,
                         BT_GATT_CHRC_NOTIFY,
                         BT_GATT_PERM_READ,
                         NULL, NULL, NULL),
  BT_GATT_CCC(data_ccc_changed,
              BT_GATT_PERM_READ | BT_GATT_PERM_WRITE),

  /* Command: Write */

  BT_GATT_CHARACTERISTIC(&g_ai_command_uuid.uuid,
                         BT_GATT_CHRC_WRITE,
                         BT_GATT_PERM_WRITE,
                         NULL, NULL, NULL),
);

/****************************************************************************
 * Public API
 ****************************************************************************/

bool sf32lb52_ble_timesync_pending(void)
{
  return g_timesync.pending;
}

void sf32lb52_ble_timesync_get(uint32_t *utc, int16_t *tz)
{
  *utc = g_timesync.utc_seconds;
  *tz = g_timesync.tz_offset_min;
  g_timesync.pending = false;
}

bool sf32lb52_ble_is_connected(void)
{
  return g_connected;
}

void sf32lb52_bt_register_custom_services(void)
{
  /* BT_GATT_SERVICE_DEFINE already registers the service at
   * link time.  This function is called to signal that the
   * service is available.
   */

  printf("BLE: AI Watch GATT service registered\n");
}

